import{_ as n,o,c as t,ag as a}from"./chunks/framework.D5hoimZQ.js";const d=JSON.parse('{"title":"🔬 科学快报 | 2026年7月13日（第 ? 期 · 事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-07-13.md","filePath":"science-log/src/reconstructed/2026-07-13.md"}'),s={name:"science-log/src/reconstructed/2026-07-13.md"};function e(g,r,i,l,h,p){return o(),t("div",null,[...r[0]||(r[0]=[a('<h1 id="🔬-科学快报-2026年7月13日-第-期-·-事后重建版" tabindex="-1">🔬 科学快报 | 2026年7月13日（第 ? 期 · 事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年7月13日-第-期-·-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年7月13日（第 ? 期 · 事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 说明：2026-07-13 为<strong>周一</strong>。CrossRef 当日命中：Nature（0028-0836）11 条，其中研究论文 <code>10.1038/s41586-…</code> 仅 <strong>2 条</strong>（1 条为 Author Correction，实质研究论文 1 条）；Science 系（10.1126）5 条，<strong>全部为新闻/评论</strong>（无研究论文）；PNAS（0027-8424）20 条。故科学 5 篇取自<strong>当日真实命中</strong>（Nature 1 + PNAS 4），AI 5 篇取自 arXiv cs.AI 当日投稿（30 条命中）。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 ｜ 重建日：2026-11-05</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="☀️-会「自我转化」的添加剂-把溴基钙钛矿的光致相分离摁住" tabindex="-1">☀️ 会「自我转化」的添加剂，把溴基钙钛矿的光致相分离摁住 <a class="header-anchor" href="#☀️-会「自我转化」的添加剂-把溴基钙钛矿的光致相分离摁住" aria-label="Permalink to &quot;☀️ 会「自我转化」的添加剂，把溴基钙钛矿的光致相分离摁住&quot;">​</a></h3><p><strong>Perovskite–organic tandem solar cells with a photo-transformable stabilizer</strong><em>Nature（2026）</em></p><p>宽带隙混合卤素钙钛矿（高溴含量）是钙钛矿—有机叠层电池的前电池材料，但它天生有两个毛病：结晶初期卤素分布不均，以及光照下溴碘分离。中科院化学研究所有机固体院重点实验室（通讯邮箱 <a href="mailto:menglei@iccas.ac.cn" target="_blank" rel="noreferrer">menglei@iccas.ac.cn</a>、liyf@iccas.ac.cn，合作单位含苏州大学）把一种<strong>可光转化添加剂 TDB</strong>（4-[3-(三氟甲基)-3H-双吖丙啶-3-基]苄铵盐）加进前驱液，做成了两阶段策略：<strong>结晶期</strong>它抑制富溴相快速析出、退火时加速卤素互混，改善初始均匀性；<strong>工作光照期</strong>双吖丙啶光解生成的新物种在晶界表面吸附更强，抑制碘相关缺陷、削弱缺陷辅助俘获与离子迁移，从而缓解光致卤素分离。代表性宽带隙电池（Eg=1.88 eV）效率 20.01%、开路电压 1.42 V、填充因子 85.13%；单结叠成钙钛矿—有机叠层后效率 28.80%，<strong>认证稳态 28.04%</strong>，ISOS-L-1 协议下运行 625 h 仍保持初始效率 90%。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10869-x" target="_blank" rel="noreferrer">10.1038/s41586-026-10869-x</a></p><h3 id="🌿-卷须「打卷」的动力不是拉力-而是自己攒下的内应力" tabindex="-1">🌿 卷须「打卷」的动力不是拉力，而是自己攒下的内应力 <a class="header-anchor" href="#🌿-卷须「打卷」的动力不是拉力-而是自己攒下的内应力" aria-label="Permalink to &quot;🌿 卷须「打卷」的动力不是拉力，而是自己攒下的内应力&quot;">​</a></h3><p><strong>Internal stress controls tendril writhing dynamics in climbing plants</strong><em>PNAS（2026）</em></p><p>黄瓜卷须被轴向拉伸时怎么卷、卷多少？格勒诺布尔-阿尔卑斯大学、里昂高师与巴黎西岱大学（Émilien Dilly、Julien Derr、Dražen Zanchi）做了定量实验：<strong>低拉力下曲率随时间指数饱和到某一极限值</strong>；<strong>超过临界力</strong>卷须干脆卷不起来，但体内却积累了「想卷」的残余曲率——一旦卸载就显现出来。生长场测量表明曲率来自<strong>差异生长</strong>，而非外力塑形。他们据此建立<strong>双条带几何的自向性形态弹性生长模型</strong>（其中一条带做机械敏感生长），并证明无外载时曲率生成只受内应力限制；再把卷须近似为 <strong>Kirchhoff 杆</strong>，就把「实际曲率 ↔ 有限外力」连了起来。这解释了攀援植物为何能在没有外界模板的情况下自发形成螺旋——<strong>形状是生长写进材料里的预应力，拉力只是读出它的探针</strong>。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2537010123" target="_blank" rel="noreferrer">10.1073/pnas.2537010123</a></p><h3 id="🔬-不用「一个个点亮」-连续发光的同种荧光分子也能被分开" tabindex="-1">🔬 不用「一个个点亮」：连续发光的同种荧光分子也能被分开 <a class="header-anchor" href="#🔬-不用「一个个点亮」-连续发光的同种荧光分子也能被分开" aria-label="Permalink to &quot;🔬 不用「一个个点亮」：连续发光的同种荧光分子也能被分开&quot;">​</a></h3><p><strong>Uninterrupted optical resolution of identical point scatterers undergoing nanometric changes in distance</strong><em>PNAS（2026）</em></p><p>超分辨荧光显微（STORM/PALM 一路）有个硬前提：相距远小于衍射极限的<strong>同种</strong>荧光分子必须<strong>先后发光</strong>，才能被逐个定位；一旦大家都亮着，图像就糊成一团。海德堡大学 ZMBH、马普多学科自然科学研究所与马普医学研究所（Thomas A. Hensel、Ole L. Schwarz、Tim Karrasch、Kerstin Göpfrich、<strong>Stefan W. Hell</strong>）在这篇里给出概念框架：用带<strong>强度零点</strong>的激发光束（MINFLUX 思路）扫描亚衍射区域时，分子位置可由其在零点附近的<strong>光子到达率差异</strong>直接读出，因此<strong>无需中断发射</strong>；论文进一步论证，现有荧光显微可达的探测速率<strong>足以</strong>支撑对<strong>恒定发光、位置随机抖动</strong>的点散射体的连续分辨与追踪，包括纳米级间距变化。意义在于：把「超分辨」从<strong>时间上分离</strong>（让分子轮流熄灯）转为<strong>空间上编码</strong>（让零点位置说话），使活体中毫秒级构象/位移过程变得可测。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2604558123" target="_blank" rel="noreferrer">10.1073/pnas.2604558123</a></p><h3 id="🦠-肠内分泌细胞是迷走神经的「路标」" tabindex="-1">🦠 肠内分泌细胞是迷走神经的「路标」 <a class="header-anchor" href="#🦠-肠内分泌细胞是迷走神经的「路标」" aria-label="Permalink to &quot;🦠 肠内分泌细胞是迷走神经的「路标」&quot;">​</a></h3><p><strong>Enteroendocrine cells wire the gut–brain vagal axis</strong><em>PNAS（2026）</em></p><p>迷走感觉神经如何长到肠壁上、形成肠—脑感觉网络，长期不清楚。俄亥俄州立大学、华盛顿大学圣路易斯与德国维尔茨堡大学等机构合作（Alexander Runyon、Peizhao Zhang、Andy J. Fischer、Michael L. Nonet、Christina Lillesaar、Lihua Ye），用<strong>斑马鱼遗传模型</strong>逐日追踪肠道迷走网络发育：迷走感觉神经元在<strong>受精后 2 天</strong>开始支配肠道，神经纤维<strong>朝着新形成的肠内分泌细胞（EEC）分支生长</strong>；新生 EEC 基底部有活跃的<strong>肌动蛋白丝</strong>，使它能与迷走感觉神经元发生<strong>物理接触/牵拉</strong>。这把 EEC 从「分泌激素的化学传感器」升级为<strong>发育期的机械性导航桩</strong>：肠道先造出 EEC，神经再顺着它们布线。对理解肠—脑轴的意义是双向的——既解释了迷走神经支配的空间特异性，也提示 EEC 发育异常可能直接造成「线路接错」型的内脏感觉障碍。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2600339123" target="_blank" rel="noreferrer">10.1073/pnas.2600339123</a></p><h3 id="🌊-单个浮游植物周围的「化学晕」-浓度梯度比理想扩散陡得多" tabindex="-1">🌊 单个浮游植物周围的「化学晕」，浓度梯度比理想扩散陡得多 <a class="header-anchor" href="#🌊-单个浮游植物周围的「化学晕」-浓度梯度比理想扩散陡得多" aria-label="Permalink to &quot;🌊 单个浮游植物周围的「化学晕」，浓度梯度比理想扩散陡得多&quot;">​</a></h3><p><strong>Raman imaging of the phycosphere reveals sharp gradients of organic matter exuded by single phytoplankton cells</strong><em>PNAS（2026）</em></p><p>浮游植物会向水体分泌大量有机物，在细胞周围形成一个叫<strong>藻际（phycosphere）<strong>的微环境，是藻—菌互作的主战场。但此前从没有人</strong>直接测出</strong>单细胞周围的化学梯度，形状一律按「理想扩散」假设（平滑、宽缓）。南加州大学与苏黎世联邦理工（Zachary C. Landry、Riccardo Foffi、Valerio Anelli、Paolo Arosio 等）用<strong>拉曼显微光谱</strong>，对半径从 <strong>2.5 μm 到 60 μm</strong> 的不同物种单细胞，逐微米测出代谢物<strong>岩藻黄素（fucoxanthin）<strong>的浓度剖面。结果显示梯度</strong>锐利</strong>、明显偏离理想扩散的预测。这意味着藻际不是一团均匀的「营养汤」，而是<strong>厚度只有几微米的强场</strong>：细菌要在极短距离内感知并竞争，藻—菌信号交换的空间尺度被重新定义，也直接影响海洋碳泵模型中「溶解有机物如何被细菌截获」的参数化。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2535317123" target="_blank" rel="noreferrer">10.1073/pnas.2535317123</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="⚙️-soap-与-muon-在上千亿-token-规模上稳定压过-adamw" tabindex="-1">⚙️ SOAP 与 Muon 在上千亿 token 规模上稳定压过 AdamW <a class="header-anchor" href="#⚙️-soap-与-muon-在上千亿-token-规模上稳定压过-adamw" aria-label="Permalink to &quot;⚙️ SOAP 与 Muon 在上千亿 token 规模上稳定压过 AdamW&quot;">​</a></h3><p><strong>SOAP, Muon, and Beyond: Pushing LLM Pretraining Scales</strong><em>arXiv（2026）</em></p><p>Muon、SOAP 这类<strong>高阶/预条件优化器</strong>收敛比 AdamW 快，但计算开销与数值稳定性让它们难以上规模。该工作（Mikail Khona、Aditya Vavre、Boxiang Wang、Deyu Fu、Hao Wu、Mike Chrzanowski 等）先定位 <strong>SOAP 在大 batch 下的失稳</strong>，用<strong>逐步 QR 正交化</strong>与改进的预条件策略<strong>消除 loss spike</strong>；再用 <strong>update-RMS 匹配</strong>做跨优化器的公平学习率迁移，从而在同等有效步长下比较 SOAP / Muon / AdamW，并顺带评估 Muon 的正交化质量。实验覆盖<strong>数十亿参数、数万亿 token</strong>：SOAP 与 Muon 在本规模上<strong>一致优于 AdamW</strong>；当 next-token 预测的 batch 放大到 <strong>1 亿 token</strong> 时，两者仍保持稳定与质量，<strong>AdamW 开始退化</strong>。工程侧给出兼容 <strong>Megatron-LM</strong> 的<strong>逐层分布式优化器</strong>实现，平衡显存、隐藏通信且<strong>不对优化器计算做近似</strong>——即保住收敛收益。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.20548" target="_blank" rel="noreferrer">2607.20548</a></p><h3 id="🧭-整流流模型的两种预测目标-可以兼得" tabindex="-1">🧭 整流流模型的两种预测目标，可以兼得 <a class="header-anchor" href="#🧭-整流流模型的两种预测目标-可以兼得" aria-label="Permalink to &quot;🧭 整流流模型的两种预测目标，可以兼得&quot;">​</a></h3><p><strong>Self-Consistent Flow: Unifying Velocity and Endpoint Prediction for Rectified Flow Models</strong><em>arXiv（2026）</em></p><p>在整流流（rectified flow）生成模型里，网络可以预测<strong>瞬时速度</strong>，也可以预测<strong>数据端点</strong>，两种参数化的经验行为不同，但「为什么不同、怎么结合」此前不清楚。该文（Xu Han、Jiajing Hu、Li-Ping Liu）做了误差分析：<strong>预测端点</strong>提供清晰稳定的训练信号，稳住优化；<strong>预测速度</strong>在数据流形附近维持稳定的采样动力学。据此提出 <strong>SC-Flow</strong>——用一条<strong>轻量一致性损失</strong>，让单个网络<strong>同时预测局部速度与数据端点</strong>，两个预测之间的一致性本身成为正则项，提升生成质量。方法<strong>不改架构</strong>、算力开销极小；在图像生成任务上显著稳定优化、提高生成路径的<strong>直线度</strong>，从而明显改善生成质量。这条思路的普适含义是：<strong>同一个物理量的两种等价表示，其误差结构互补；让它们互相校验，等于免费加了一条约束。</strong></p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.12171" target="_blank" rel="noreferrer">2607.12171</a></p><h3 id="📝-把人工评审意见「编译」成规则-编码智能体跨会话不再重犯" tabindex="-1">📝 把人工评审意见「编译」成规则，编码智能体跨会话不再重犯 <a class="header-anchor" href="#📝-把人工评审意见「编译」成规则-编码智能体跨会话不再重犯" aria-label="Permalink to &quot;📝 把人工评审意见「编译」成规则，编码智能体跨会话不再重犯&quot;">​</a></h3><p><strong>Self-Improving AI Coding Agents Through Accumulated Behavioral Rules: A Closed-Loop Framework</strong><em>arXiv（2026）</em></p><p>LLM 编码智能体跨会话反复犯<strong>同一类</strong>错误，因为它没有机制留存人类评审的纠正。该框架（Aditya Aggarwal、Nahid Farhady Ghalaty）把<strong>每一条被接受的评审意见</strong>编码成<strong>持久行为规则</strong>，让智能体可自检的错误类别集合持续扩张。三件套：版本控制指令文件里<strong>不断累积的规则集</strong>、提交前执行的<strong>自我评审清单</strong>、以及保证规则集膨胀后仍<strong>自洽</strong>的自动校验。在 35+ 微服务的生产平台部署中，规则集从 <strong>5 条长到 18 条</strong>，另有 <strong>15+ 条语言特定规范</strong>与 <strong>15 项自检清单</strong>，全部来自真实评审反馈；11 场记录在案的工作会话（代码生成、PR 评审、事故调查、跨服务重构）显示：<strong>规则覆盖的错误类别复发率降到 0%</strong>，评审精力从「低级正确性」上移到「设计层校验」，且能在异构智能体界面间迁移。与 Reflexion / ExpeL / Voyager 相比，关键差别是<strong>跨会话持久</strong>——记忆不在上下文里，而在仓库里。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.13091" target="_blank" rel="noreferrer">2607.13091</a></p><h3 id="🦿-会走就该会跑-把行走策略「长」成跑" tabindex="-1">🦿 会走就该会跑：把行走策略「长」成跑 <a class="header-anchor" href="#🦿-会走就该会跑-把行走策略「长」成跑" aria-label="Permalink to &quot;🦿 会走就该会跑：把行走策略「长」成跑&quot;">​</a></h3><p><strong>GaitSpan: Growing Humanoid Locomotion from Walking to Running</strong><em>arXiv（2026）</em></p><p>现在让机器人跑，通常靠<strong>规定步态时序</strong>、<strong>模仿动作片段</strong>、训练专家策略再切换或蒸馏——行为好看，但对<strong>连续速度指令</strong>、地形与形体的灵活性差。GaitSpan（Kwan-Yee Lin、Zilin Wang、Janelle J. Liu、Stella X. Yu）换了个思路：<strong>把行走当种子技能</strong>，视其为可复用的运动结构（平衡、支撑、身体协调、触地转换），在此基础上<strong>按新节律重新生成、拉长/抬高步幅、再用残差修正</strong>。三步：① <strong>节律生成</strong>——冻结行走策略，用多个<strong>内部时钟</strong>调制它，并学习<strong>指令条件下的规范动作组合</strong>；② <strong>步幅成形</strong>——用受<strong>弹簧负载倒立摆（SLIP）<strong>动力学启发的物理目标，奖励与高指令速度匹配的动态步态；③ <strong>残差适应</strong>——吸收前两步解释不了的细节。结果是</strong>首个单条指令条件化的人形策略</strong>，连续覆盖走、慢跑与奔跑，而不是若干条拼起来的专家。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.12114" target="_blank" rel="noreferrer">2607.12114</a></p><h3 id="☢️-cbrn「能力抬升」怎么才算数-把评估拆成可独立执行的部件" tabindex="-1">☢️ CBRN「能力抬升」怎么才算数：把评估拆成可独立执行的部件 <a class="header-anchor" href="#☢️-cbrn「能力抬升」怎么才算数-把评估拆成可独立执行的部件" aria-label="Permalink to &quot;☢️ CBRN「能力抬升」怎么才算数：把评估拆成可独立执行的部件&quot;">​</a></h3><p><strong>A Threshold Exceedance Framework for CBRN Uplift Evaluation in Frontier Language Models</strong><em>arXiv（2026）</em></p><p>政策制定者需要知道：模型访问是否让<strong>非专家</strong>规划 CBRN（化生放核）滥用的能力<strong>实质性</strong>超过只用公开工具。但既有评估在非专家定义、威胁范围、基线、评分细则与判定规则上各不相同，结果无法横向比较。本文（Rahul Gupta、Abhinav Mohanty、Payal Motwani、Venkatesh Saligrama、Satyapriya Krishna、Connor Harris）提出<strong>阈值超越判据（TEC）框架</strong>，把一次 uplift 研究拆成三个<strong>可独立执行</strong>的部件：非专家参与者资格判定、CBRN 威胁范围界定、以及<strong>uplift 的统计估计</strong>。据此做了大规模实证，区分<strong>生成式 uplift</strong>（从零起草方案）与<strong>修订式 uplift</strong>（改进已有方案），产出覆盖各 CBRN 领域的攻击方案，由<strong>领域专家评审</strong>定级。结果显示<strong>明显的域间异质性</strong>：在受控的预发布评估中，模型辅助方案有时能拿到「与专家相当」的教学评级，但<strong>确证的实质性提升在多数设定下有限</strong>。方法论价值大于结论：<strong>把「是否危险」变成可复算的统计命题</strong>。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.12200" target="_blank" rel="noreferrer">2607.12200</a></p><hr><blockquote><p>📅 日期：2026-07-13 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇</p></blockquote>',46)])])}const u=n(s,[["render",e]]);export{d as __pageData,u as default};
